// Per-tenant quota guard
function quotaGuard(req, res, next) {
  const tenant = req.headers['x-tenant-id'] || req.params.tenantId;
  const usage = getTenantUsage(tenant);
  if (usage >= QUOTA) return res.status(429).json({error: 'quota_exceeded'});
  next();
}
```

